# Regenerate the payload with SDK RHUN_TRANSFORM_ASM_OUT and
# TestSnippetTransformNativeVectorExport, replacing after the marker below.
.include "rhun.inc"
.bss
.p2align 3
out: .zero SB_SIZE
.text
FN main
    PROLOGUE
    mov r15, [rip + g_mem_live]
    lea r12, [rip + .Ltf_vectors]
    xor r13d, r13d
.Ltf_test:
    cmp qword ptr [r12], 0
    je .Ltf_ok
    mov rdi, [r12 + 8]
    xor esi, esi
    call snippet_regex_new
    test rax, rax
    jz .Ltf_fail
    mov rbx, rax
    mov rdi, rax
    mov rsi, [r12]
    call snippet_transform_execute
    mov r14, rax
    mov r8, [r12 + 32]
    test r8, r8
    setz r8b
    movzx r8d, r8b
    cmp rcx, r8
    jne .Ltf_fail
    cmp rdx, [r12 + 24]
    jne .Ltf_fail
    test ecx, ecx
    jz 1f
    mov rdi, rax
    mov rsi, [r12 + 16]
    call memeq
    test eax, eax
    jz .Ltf_fail
    jmp 2f
1:  test r14, r14
    jnz .Ltf_fail
2:  mov rax, [rbx + RX_error]
    cmp rax, [r12 + 32]
    jne .Ltf_fail
    mov rax, [rbx + RX_tstage]
    cmp rax, [r12 + 40]
    jne .Ltf_fail
    mov rax, [rbx + RX_trecord]
    cmp rax, [r12 + 48]
    jne .Ltf_fail
    mov rax, [rbx + RX_work]
    cmp rax, [r12 + 56]
    jne .Ltf_fail
    cmp qword ptr [rbx + RX_ready], 0
    jne .Ltf_fail
    cmp qword ptr [rbx + RX_hasmatch], 0
    jne .Ltf_fail
    cmp qword ptr [rbx + RX_program], 0
    jne .Ltf_fail
    cmp qword ptr [rbx + RX_input], 0
    jne .Ltf_fail
    cmp qword ptr [rbx + RX_code], 0
    jne .Ltf_fail
    mov rdi, r14
    call mem_free
    mov rdi, rbx
    call snippet_regex_free
    cmp r15, [rip + g_mem_live]
    jne .Ltf_fail
    inc r13
    add r12, 64
    jmp .Ltf_test
.Ltf_ok:
    lea rdi, [rip + ok]
    call log_cstr
    xor eax, eax
    EPILOGUE
.Ltf_fail:
    lea rdi, [rip + failed]
    call log_cstr
    lea rdi, [rip + out]
    mov rsi, r13
    call sb_push_u64
    lea rdi, [rip + out]
    mov esi, 32
    call sb_push_byte
    lea rdi, [rip + out]
    mov rsi, [rbx + RX_error]
    call sb_push_u64
    lea rdi, [rip + out]
    mov esi, 32
    call sb_push_byte
    lea rdi, [rip + out]
    mov rsi, [rbx + RX_tstage]
    call sb_push_u64
    lea rdi, [rip + out]
    mov esi, 32
    call sb_push_byte
    lea rdi, [rip + out]
    mov rsi, [rbx + RX_trecord]
    call sb_push_u64
    lea rdi, [rip + out]
    mov esi, 32
    call sb_push_byte
    lea rdi, [rip + out]
    mov rsi, [rbx + RX_work]
    call sb_push_u64
    lea rdi, [rip + out]
    mov esi, 10
    call sb_push_byte
    mov rdi, [rip + out + SB_ptr]
    mov rsi, [rip + out + SB_len]
    call log_write
    mov eax, 1
    EPILOGUE
